// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();

        vm.prank(address(this));
        c.updateRoundImplementation(payable(address(1)));

        vm.prank(address(this));
        c.updateAlloSettings(address(2));

        address caller = address(0x1234);

        vm.prank(caller);
        bool ok;
        try c.create("", caller) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
